#!/usr/bin/env python3
"""Generate wgmma_lowp_n_test.cu gtest covering fp8/tf32/int8 WGMMA at
N=16/64/128/256 (SS) and N=64 (RS), exact-value CPU reference."""
import sys
sys.path.insert(0, "/data/kernel_tests/fgs_bf16_cluster/lowp")
import importlib.util
spec = importlib.util.spec_from_file_location(
    "genwp", "/data/kernel_tests/fgs_bf16_cluster/lowp/gen_wgmma_probe.py")
genwp = importlib.util.module_from_spec(spec)
spec.loader.exec_module(genwp)

HEADER = r"""
// Generated by tests/src/wgmma/gen_wgmma_lowp_n_test.py. Do not edit.
// WGMMA fp8/tf32/int8 integration tests across N (sm_90a).
#include <gtest/gtest.h>

#include <cmath>
#include <cstdint>
#include <cstring>
#include <random>
#include <vector>

#define WG_THREADS 128

static __device__ __forceinline__ uint32_t smem_u32(const void *p) {
  return (uint32_t)__cvta_generic_to_shared(p);
}
static __host__ __device__ __forceinline__ uint32_t swz128(uint32_t o) {
  return o ^ ((o & 0x380u) >> 3);
}
static __host__ __device__ __forceinline__ int kmajx(int r, int k, int esz) {
  int e16 = 16 / esz;
  uint32_t off = (uint32_t)(r / 8) * 1024u + (uint32_t)(r % 8) * 128u +
                 (uint32_t)(k / e16) * 16u + (uint32_t)(k % e16) * esz;
  return (int)(swz128(off) / esz);
}
static __device__ __forceinline__ uint64_t gdesc(const void *p, uint32_t lbo,
                                                 uint32_t sbo,
                                                 uint32_t swizzle) {
  uint32_t a = smem_u32(p);
  uint64_t d = 0;
  d |= (uint64_t)((a >> 4) & 0x3FFF);
  d |= (uint64_t)((lbo >> 4) & 0x3FFF) << 16;
  d |= (uint64_t)((sbo >> 4) & 0x3FFF) << 32;
  d |= (uint64_t)(swizzle & 0x3) << 62;
  return d;
}
static __host__ __device__ __forceinline__ void acc_coord(int lane, int reg4,
                                                          int &row, int &col) {
  int c = lane % 4, r = (lane / 4) % 8, mb = lane / 32;
  row = r + 16 * mb + 8 * ((reg4 >> 1) & 1);
  col = 2 * c + (reg4 & 1);
}

static float e4m3_f32(uint8_t b) {
  int s = (b >> 7) & 1, e = (b >> 3) & 0xF, m = b & 7;
  float v = 0.0f;
  if (e == 0) v = m ? ldexpf(m / 8.0f, -6) : 0.0f;
  else if (e == 0xF && m == 7) v = NAN;
  else v = ldexpf(1.0f + m / 8.0f, e - 7);
  return s ? -v : v;
}
static float e5m2_f32(uint8_t b) {
  int s = (b >> 7) & 1, e = (b >> 2) & 0x1F, m = b & 3;
  float v = 0.0f;
  if (e == 0) v = m ? ldexpf(m / 4.0f, -14) : 0.0f;
  else if (e == 0x1F) v = m ? NAN : INFINITY;
  else v = ldexpf(1.0f + m / 4.0f, e - 15);
  return s ? -v : v;
}
static float bits_f32(uint32_t u) { float f; memcpy(&f, &u, 4); return f; }
static uint32_t f32_bits(float f) { uint32_t u; memcpy(&u, &f, 4); return u; }
static float tf32_ref(float f) {
  return bits_f32(f32_bits(f) & ~0x1FFFu);
}
static uint8_t f32_e4m3(float value) {
  if (std::isnan(value)) return 0x7f;
  uint8_t sign = std::signbit(value) ? 0x80 : 0;
  float m = std::fabs(value);
  if (m > 448.0f || std::isinf(m)) m = 448.0f;
  if (m == 0.0f) return sign;
  if (m < ldexpf(1.0f, -6)) {
    float q = m / ldexpf(1.0f, -9);
    int mant = (int)std::floor(q);
    float fr = q - mant;
    if (fr > 0.5f || (fr == 0.5f && (mant & 1))) ++mant;
    if (mant == 0) return sign;
    if (mant >= 8) return sign | 0x08;
    return sign | mant;
  }
  int ex = 0;
  float fr = std::frexp(m, &ex) * 2.0f;
  int ee = ex - 1 + 7;
  float q = (fr - 1.0f) * 8.0f;
  int mant = (int)std::floor(q);
  float rem = q - mant;
  if (rem > 0.5f || (rem == 0.5f && (mant & 1))) ++mant;
  if (mant == 8) { mant = 0; ++ee; }
  if (ee > 15 || (ee == 15 && mant > 6)) return sign | 0x7e;
  return sign | ((ee << 3) | mant);
}
static uint8_t f32_e5m2(float value) {
  if (std::isnan(value)) return 0x7f;
  uint8_t sign = std::signbit(value) ? 0x80 : 0;
  float m = std::fabs(value);
  if (m > 57344.0f || std::isinf(m)) m = 57344.0f;
  if (m == 0.0f) return sign;
  if (m < ldexpf(1.0f, -14)) {
    float q = m / ldexpf(1.0f, -16);
    int mant = (int)std::floor(q);
    float fr = q - mant;
    if (fr > 0.5f || (fr == 0.5f && (mant & 1))) ++mant;
    if (mant == 0) return sign;
    if (mant >= 4) return sign | 0x04;
    return sign | mant;
  }
  int ex = 0;
  float fr = std::frexp(m, &ex) * 2.0f;
  int ee = ex - 1 + 15;
  float q = (fr - 1.0f) * 4.0f;
  int mant = (int)std::floor(q);
  float rem = q - mant;
  if (rem > 0.5f || (rem == 0.5f && (mant & 1))) ++mant;
  if (mant == 4) { mant = 0; ++ee; }
  if (ee > 30) return sign | 0x7b;
  return sign | ((ee << 2) | mant);
}
"""


def gen_test_case(c):
    """Emit a gtest TEST body for case c (exact inputs, bitwise compare)."""
    fam = c["fam"]
    N = c["N"]
    K = {"fp8": 32, "s8": 32, "u8": 32, "tf32": 8}[fam]
    esz = {"fp8": 1, "s8": 1, "u8": 1, "tf32": 4}[fam]
    el_t = {1: "uint8_t", 4: "uint32_t"}[esz]
    acc_t = "int32_t" if fam in ("s8", "u8") else "float"
    name = c["name"]
    if fam == "fp8":
        enc_a = "f32_e4m3" if c["at"] == "e4m3" else "f32_e5m2"
        enc_b = "f32_e4m3" if c["bt"] == "e4m3" else "f32_e5m2"
        dec_a = "e4m3_f32" if c["at"] == "e4m3" else "e5m2_f32"
        dec_b = "e4m3_f32" if c["bt"] == "e4m3" else "e5m2_f32"
        gen_in = f"""
  for (auto &v : Av) v = {enc_a}(pool[gen() % 17]);
  for (auto &v : Bv) v = {enc_b}(pool[gen() % 17]);"""
        a_val = f"{dec_a}(Av[row * {K} + k])"
        b_val = f"{dec_b}(Bv[col * {K} + k])"
    elif fam == "tf32":
        gen_in = """
  for (auto &v : Av) v = f32_bits(pool[gen() % 17]);
  for (auto &v : Bv) v = f32_bits(pool[gen() % 17]);"""
        a_val = f"tf32_ref(bits_f32(Av[row * {K} + k]))"
        b_val = f"tf32_ref(bits_f32(Bv[col * {K} + k]))"
    else:
        conv_a = "(int32_t)(int8_t)" if c["at"] == "s8" else "(int32_t)(uint8_t)"
        conv_b = "(int32_t)(int8_t)" if c["bt"] == "s8" else "(int32_t)(uint8_t)"
        gen_in = """
  for (auto &v : Av) v = (uint8_t)((int)(gen() % 17) - 8);
  for (auto &v : Bv) v = (uint8_t)((int)(gen() % 17) - 8);"""
        a_val = f"{conv_a}(Av[row * {K} + k])"
        b_val = f"{conv_b}(Bv[col * {K} + k])"

    if fam in ("s8", "u8"):
        cgen = "for (auto &v : Cv) v = (uint32_t)((int)(gen() % 33) - 16);"
        ref = f"""
  for (int row = 0; row < 64; ++row)
    for (int col = 0; col < {N}; ++col) {{
      int64_t sum = 0;
      for (int k = 0; k < {K}; ++k)
        sum += (int64_t)({a_val}) * (int64_t)({b_val});
      int64_t r = sum + (int64_t)(int32_t)Cv[row * {N} + col];
      ref[row * {N} + col] = (int32_t)r;
    }}"""
    else:
        cgen = "for (auto &v : Cv) v = f32_bits((float)((int)(gen() % 17) - 8));"
        ref = f"""
  for (int row = 0; row < 64; ++row)
    for (int col = 0; col < {N}; ++col) {{
      float sum = 0.0f;
      for (int k = 0; k < {K}; ++k)
        sum += ({a_val}) * ({b_val});
      ref[row * {N} + col] = sum + refc[row * {N} + col];
    }}"""

    return f"""
TEST(WgmmaLowpN, {name}) {{
  const float pool[17] = {{-2,-1.875,-1.75,-1.625,-1.5,-1.375,-1.25,-1.125,
                          -1,-0.75,-0.5,-0.25,0,0.25,0.5,0.75,1}};
  std::vector<{el_t}> Av(64 * {K}), Bv({N} * {K});
  std::vector<uint32_t> Cv(64 * {N});
  std::mt19937 gen({c['seed']});
  {gen_in}
  {cgen}
  {el_t} *dA; {el_t} *dB; uint32_t *dC, *dOut;
  ASSERT_EQ(cudaMalloc(&dA, Av.size() * sizeof({el_t})), cudaSuccess);
  ASSERT_EQ(cudaMalloc(&dB, Bv.size() * sizeof({el_t})), cudaSuccess);
  ASSERT_EQ(cudaMalloc(&dC, Cv.size() * 4), cudaSuccess);
  ASSERT_EQ(cudaMalloc(&dOut, 64 * {N} * 4), cudaSuccess);
  ASSERT_EQ(cudaMemcpy(dA, Av.data(), Av.size() * sizeof({el_t}),
                       cudaMemcpyHostToDevice), cudaSuccess);
  ASSERT_EQ(cudaMemcpy(dB, Bv.data(), Bv.size() * sizeof({el_t}),
                       cudaMemcpyHostToDevice), cudaSuccess);
  ASSERT_EQ(cudaMemcpy(dC, Cv.data(), Cv.size() * 4, cudaMemcpyHostToDevice),
            cudaSuccess);
  kern_{name}<<<1, {{WG_THREADS}}>>>(dOut, dA, dB, dC, 1);
  ASSERT_EQ(cudaGetLastError(), cudaSuccess);
  ASSERT_EQ(cudaDeviceSynchronize(), cudaSuccess);
  std::vector<uint32_t> raw(64 * {N});
  ASSERT_EQ(cudaMemcpy(raw.data(), dOut, raw.size() * 4,
                       cudaMemcpyDeviceToHost), cudaSuccess);
  std::vector<{acc_t}> got(64 * {N}), ref(64 * {N}), refc(64 * {N});
  memcpy(got.data(), raw.data(), raw.size() * 4);
  memcpy(refc.data(), Cv.data(), Cv.size() * 4);
  {ref}
  for (int i = 0; i < 64 * {N}; ++i)
    EXPECT_EQ(got[i], ref[i]) << "index " << i;
  cudaFree(dA); cudaFree(dB); cudaFree(dC); cudaFree(dOut);
}}
"""


def main():
    cases = []
    seed = 5000
    Ns = [16, 64, 128, 256]

    def add(c):
        nonlocal seed
        seed += 1
        c["seed"] = seed
        cases.append(c)

    for at, bt in [("e4m3", "e4m3"), ("e5m2", "e5m2"), ("e4m3", "e5m2")]:
        for N in Ns:
            add(dict(fam="fp8", at=at, bt=bt, N=N, ss=True,
                     name=f"Fp8_{at}_{bt}_N{N}_SS"))
        add(dict(fam="fp8", at=at, bt=bt, N=64, ss=False,
                 name=f"Fp8_{at}_{bt}_N64_RS"))
    for N in Ns:
        add(dict(fam="tf32", at="tf32", bt="tf32", N=N, ss=True,
                 name=f"Tf32_N{N}_SS"))
    add(dict(fam="tf32", at="tf32", bt="tf32", N=64, ss=False,
             name="Tf32_N64_RS"))
    for at, bt in [("s8", "s8"), ("u8", "u8")]:
        for N in Ns:
            add(dict(fam=at, at=at, bt=bt, N=N, ss=True,
                     name=f"I8_{at}_{bt}_N{N}_SS"))
        add(dict(fam=at, at=at, bt=bt, N=64, ss=False,
                 name=f"I8_{at}_{bt}_N64_RS"))

    out = [HEADER]
    for c in cases:
        out.append(genwp.gen_kernel(c))
    for c in cases:
        out.append(gen_test_case(c))
    src = "".join(out).replace("{{WG_THREADS}}", "WG_THREADS")
    dst = ("/data/kernel_tests/fgs_bf16_cluster/FlashGPU-Sim/tests/src/wgmma/"
           "wgmma_lowp_n_test.cu")
    with open(dst, "w") as f:
        f.write(src)
    print(f"wrote {dst}: {len(cases)} tests, {len(src)} bytes")


if __name__ == "__main__":
    main()
